-- Create "actors" table
CREATE TABLE "actors" ("workspace_id" text NOT NULL, "id" text NOT NULL, "name" text NOT NULL, "kind" text NOT NULL, "owner_id" text NULL, "harness" text NULL, "archived" boolean NOT NULL DEFAULT false, "name_confirmed" boolean NOT NULL DEFAULT false, "created_at" bigint NOT NULL, "auth_subject" text NULL, "model" text NULL, "effort" text NULL, "permission_mode" text NULL, "approval_policy" text NULL, "sandbox" text NULL, "invited_by" text NULL, "role" text NULL, PRIMARY KEY ("workspace_id", "id"), CONSTRAINT "actors_owner_id_fkey" FOREIGN KEY ("workspace_id", "owner_id") REFERENCES "actors" ("workspace_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "actors_check" CHECK (((kind = 'human'::text) AND (owner_id IS NULL)) OR ((kind = 'agent'::text) AND (owner_id IS NOT NULL))), CONSTRAINT "actors_check1" CHECK ((kind = 'human'::text) = (role IS NOT NULL)), CONSTRAINT "actors_harness_check" CHECK (harness = ANY (ARRAY['pi'::text, 'claude-code'::text, 'codex'::text])), CONSTRAINT "actors_kind_check" CHECK (kind = ANY (ARRAY['human'::text, 'agent'::text])), CONSTRAINT "actors_role_check" CHECK (role = ANY (ARRAY['owner'::text, 'member'::text])));
